pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a contract that will revert on receiving Ether
        address recipient = address(new RevertingReceiver());
        // Fund recipient with some initial balance to avoid underflow in the assertion step
        vm.deal(recipient, 1 ether);

        // Deposit 10 wei as the recipient
        vm.deal(recipient, 1 ether + 10);
        vm.prank(recipient);
        c.deposit{value: 10}();

        // Attempt withdrawal; will revert because recipient rejects Ether
        vm.prank(recipient);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        // ok is false because the call reverted

        // Now withdraw again with a recipient that accepts Ether
        address attacker = address(0x1234);
        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        c.deposit{value: 5}();

        vm.prank(attacker);
        c.withdrawAll();

        // After this, the attacker should have received exactly 5 wei
        // But the buggy version still has credit[recipient] = 10 and balance = 15 (5 + 10) 
        // so a third withdrawal by recipient would succeed

        // Check that the attacker got 5 wei back (no inflation)
        assertEq(address(attacker).balance, 1 ether + 5);
    }
}

contract RevertingReceiver {
    receive() external payable {
        revert("no ether");
    }
}

