    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Scenario: Two users deposit, then one withdraws. Then the other tries to withdraw.
        // The reference will revert because balance is insufficient after the first withdrawal,
        // but the buggy version will not revert.

        address alice = address(0x1);
        address bob = address(0x2);

        // Set up deposits
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.deposit{value: 10 ether}();

        vm.deal(bob, 5 ether);
        vm.prank(bob);
        c.deposit{value: 5 ether}();

        // Alice withdraws all
        vm.prank(alice);
        c.withdrawAll();

        // Bob tries to withdraw – reference contract will revert (require fails)
        // because balance is now 0, not enough to cover bob's 5 ether.
        // Buggy version will not revert.
        vm.prank(bob);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

