pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a recipient that rejects ETH (no receive/fallback)
        address recipient = address(0x1234);

        // Fund the recipient so it can deposit
        vm.deal(recipient, 1 ether);

        // Recipient deposits 1 ether
        vm.prank(recipient);
        c.deposit{value: 1 ether}();

        // Recipient tries to withdrawAll -> should revert because transfer fails
        vm.prank(recipient);
        bool ok;
        bytes memory data;
        (ok, data) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // The reference version reverts (ok == false), the buggy version does not (ok == true)
        // but more importantly: after the failed call, the buggy version has zeroed credit[recipient]
        // while the reference version still has the credit = 1 ether.
        // We check this by calling withdrawAll again and seeing if it succeeds (buggy)
        // or reverts (reference: no credit, so no call made, returns silently).
        vm.prank(recipient);
        bool ok2;
        bytes memory data2;
        (ok2, data2) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // Reference: first call reverts, so credit[recipient] still = 1 ether.
        // When called again, the if(oCredit > 0) triggers, it tries to send again and reverts again -> ok2 == false.
        // Buggy: first call succeeds (credit set to 0, balance reduced, send fails but continue)
        // so second call sees oCredit == 0 and returns silently -> ok2 == true.
        assertTrue(ok2 == false);
    }
}

